android.extraProguardRules:
# react-native-android-widget schedules its background refresh through
# WorkManager, which builds its Room database by reflection:
# Room.databaseBuilder(ctx, WorkDatabase.class, ...) resolves
# `androidx.work.impl.WorkDatabase_Impl` with Class.forName at runtime.
# R8 cannot see that reference, so without these keeps the generated impl
# is stripped and the process dies inside
# androidx.startup.InitializationProvider -> WorkManagerInitializer.
-keep class androidx.work.impl.WorkDatabase_Impl { *; }
-keep class * extends androidx.room.RoomDatabase { <init>(); }
-keepclassmembers class * extends androidx.room.RoomDatabase { <init>(); }
-keep class * extends androidx.room.RoomDatabase { *; }
-dontwarn androidx.room.paging.**
